char *status_text = "";
if (online_sync_status == 1) {
    grim_interface_ptr->grim_set_color(
        0.2f, 1.0f, 0.2f, 0.8f);
    status_text = "Connecting server..";
} else if (online_sync_status == 5) {
    grim_interface_ptr->grim_set_color(
        0.4f, 1.0f, 0.4f, 0.8f);
    status_text = "Done..";
} else if (online_sync_status == 6) {
    grim_interface_ptr->grim_set_color(
        1.0f, 0.1f, 0.1f, 0.8f);
    status_text = "Failed..";
}

